python
def xorRegisterFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    state=0
    for x in a:
        state^=x
        out.append(state)
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int xorRegisterFirstQualifyingSlip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int state=0;for(int x:a){state^=x;out.add(state);}}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
